"""Register refinement physics weights from TRAINING gradients at a shared warm start."""
from pathlib import Path
import json,sys
import numpy as np,torch
P=Path(__file__).resolve().parents[1];sys.path.insert(0,str(P/'src'))
from lv_surrogate.models.geometry_pod import GeometryPOD
from lv_surrogate.physics.cardiac_residual import CardiacFirstStep
torch.set_num_threads(2);D=P/'data/processed/cardiac_geometry_ml';n=np.load(D/'normalizers.npz');a=np.load(D/'train.npz');device='mps';net=GeometryPOD(*[n[k] for k in ['field_mean','basis','coefficient_scale']]).float().to(device);ck=torch.load(P/'experiments/checkpoints/cardiac_geometry_models_v2/data_seed11_best.pt',map_location='cpu',weights_only=False);net.load_state_dict(ck['model']);top=torch.tensor(np.load(D/'topology.npy'),device=device);records=[]
for i in np.random.default_rng(2027).choice(len(a['targets']),8,replace=False):
 g=int(a['geometry_ids'][i]);raw=np.load(P/f'data/processed/cardiac_geometry_v1/geometry_{g:03d}.npz');own=CardiacFirstStep(raw,dtype=torch.float32,analytic_piola=True).to(device);b=[torch.tensor(a[k][i:i+1],dtype=torch.float32,device=device) for k in ['coarse','globals','edges']];u=net(*b,top)[0];data=((u-torch.tensor(a['targets'][i],dtype=torch.float32,device=device))/float(n['u_scale'])).square().mean();gd=torch.autograd.grad(data,list(net.parameters()),retain_graph=True);R=own(u,float(a['pressures'][i]),create_graph=True);eq=(R/float(raw['force_scale_N'])).square().mean();ge=torch.autograd.grad(eq,list(net.parameters()));dn=float(sum(x.square().sum() for x in gd).sqrt());en=float(sum(x.square().sum() for x in ge).sqrt());records.append({'training_case':int(i),'geometry':g,'load':int(a['load_ids'][i]),'data_gradient_norm':dn,'physics_gradient_norm':en,'balance_lambda':dn/max(en,1e-30)})
